"""mizan -- the capacity charge nobody re-measures."""

import argparse
import os
import sys
from datetime import date, datetime

from . import agents, report, rules, units
from .config import Config


def build_parser():
    p = argparse.ArgumentParser(
        prog="mizan",
        description="District cooling capacity review: the evidence test, "
                    "justified demand and the recoverable ceiling are "
                    "computed, never generated by a model. A unit whose "
                    "evidence window cannot have observed peak demand gets "
                    "no finding at all.",
    )
    p.add_argument("units", help="allocation schedule CSV")
    p.add_argument("--readings", default=None,
                   help="monthly readings CSV (default: alongside the units "
                        "file, named readings.csv)")
    p.add_argument("-o", "--out", default="review.csv", help="review CSV")
    p.add_argument("--config", default=None,
                   help="JSON overriding evidence standards and tolerances")
    p.add_argument("--today", default=None,
                   help="YYYY-MM-DD, for reproducible runs")
    p.add_argument("--no-agents", action="store_true",
                   help="computed review only; no model calls")
    p.add_argument("--fail-on", default="none",
                   choices=("none", "over-allocated", "under-allocated", "held"),
                   help="exit non-zero at this state (for a scheduled run)")
    p.add_argument("--no-colour", action="store_true")
    return p


def build_task(portfolio):
    """One task per run, or none.

    `blocked_units` carries the units the engine ruled unprojectable. They
    are passed to the gate so claim language cannot attach to them -- the
    engine refused to make a finding, and the drafting layer may not
    manufacture one.
    """
    if not portfolio.claimable():
        return None
    facts = portfolio.facts()
    blocked = [f.unit_id for f in portfolio.by_state("INSUFFICIENT_EVIDENCE")]
    return {
        "review_id": portfolio.today.isoformat(),
        "label": f"{len(portfolio.claimable())} claimable unit(s)",
        "facts": facts,
        "allowed": agents.expand_evidence(facts, blocked_units=blocked),
    }


def main(argv=None):
    args = build_parser().parse_args(argv)

    today = date.today()
    if args.today:
        try:
            today = datetime.strptime(args.today, "%Y-%m-%d").date()
        except ValueError:
            print(f"mizan: --today must be YYYY-MM-DD, got {args.today}",
                  file=sys.stderr)
            return 2

    try:
        cfg = Config.load(args.config)
    except (OSError, ValueError) as exc:
        print(f"mizan: config: {exc}", file=sys.stderr)
        return 2

    if not os.path.isfile(args.units):
        print(f"mizan: {args.units} not found", file=sys.stderr)
        return 2

    readings_path = args.readings or os.path.join(
        os.path.dirname(os.path.abspath(args.units)), "readings.csv")
    if not os.path.isfile(readings_path):
        print(f"mizan: {readings_path} not found -- pass --readings",
              file=sys.stderr)
        return 2

    try:
        unit_rows = units.load_units(args.units)
        reading_rows = units.load_readings(readings_path)
    except (OSError, ValueError) as exc:
        print(f"mizan: {exc}", file=sys.stderr)
        return 2

    portfolio = rules.assess(unit_rows, reading_rows, cfg, today)

    task = build_task(portfolio)
    agentic = not args.no_agents and task is not None
    if agentic:
        try:
            [task] = agents.run([task])
        except agents.AgentUnavailable as exc:
            print(f"mizan: {exc}", file=sys.stderr)
            print("mizan: falling back to the computed review.", file=sys.stderr)
            agentic = False

    if agentic:
        agents.gate(task, task["allowed"])
    else:
        task = None

    print(report.terminal(portfolio, cfg, agentic, task,
                          use_colour=not args.no_colour))

    report.write_csv(args.out, portfolio)
    print(f"  review -> {args.out}")
    print("")

    if args.fail_on == "over-allocated" and portfolio.by_state("OVER_ALLOCATED"):
        return 1
    if args.fail_on == "under-allocated" and portfolio.by_state("UNDER_ALLOCATED"):
        return 1
    if args.fail_on == "held" and task and task.get("status") == "held":
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
